export const equipmentClass=id=>ITEMS[id]?.classId||ITEMS[id]?.weaponClass||(['sword','bow','mage'].includes(id)?id:id==='shield'?'sword':null);
export const isBagSlot=i=>i>=6&&i<18||i>=20;
export const canEquip=(id,slot,classId)=>!id||isBagSlot(slot)||(!equipmentClass(id)||equipmentClass(id)===classId);
