export const SLOT_NAMES=['Оружие','Доп. оружие / щит','Шлем','Нагрудник','Штаны','Обувь'];
export function createInventory(){return Array(20).fill(null)}
export const itemLimit=id=>({order_tonic:5,mary_ale:12,return_bone:5}[id]??Infinity);
export function inventoryError(slots,id,count=1){if(countItem(slots,id)+count>itemLimit(id))return {order_tonic:'Можно нести не больше 5 боевых настоек.',mary_ale:'Можно нести не больше 12 порций эля.',return_bone:'Можно нести не больше 5 косточек возвращения.'}[id];if(!slots.some((s,i)=>isBagSlot(i)&&(!s||s.id===id)))return 'В сумке нет свободных ячеек.';return ''}
export function addItem(slots,id,count=1){if(inventoryError(slots,id,count))return false;const same=slots.findIndex((s,i)=>isBagSlot(i)&&s?.id===id);const index=same>=0?same:slots.findIndex((s,i)=>isBagSlot(i)&&!s);if(index<0)return false;if(slots[index])slots[index].count+=count;else slots[index]={id,count};return true}
export function countItem(slots,id){return slots.reduce((n,s)=>n+(s?.id===id?s.count:0),0)}
export function removeItem(slots,id,count=1){if(countItem(slots,id)<count)return false;for(let i=0;i<slots.length&&count;i++){if(slots[i]?.id!==id)continue;const take=Math.min(count,slots[i].count);slots[i].count-=take;count-=take;if(!slots[i].count)slots[i]=null}return true}
export function moveItem(slots,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=slots.length||to>=slots.length||from===to||!slots[from])return false;const fits=(item,index)=>!item||isBagSlot(index)||(index>=18&&index<20?ITEMS[item.id]?.slot==='ring':(ITEMS[item.id]?.slot===index||item.id==='torch'&&index===1));if(!fits(slots[from],to)||!fits(slots[to],from))return false;if(slots[to]?.id===slots[from].id&&isBagSlot(to)){slots[to].count+=slots[from].count;slots[from]=null}else [slots[from],slots[to]]=[slots[to],slots[from]];return true}
